389	// facts.ts
390	import type { Session, Facts } from './schema';
391	export function computeFacts(sessions: Session[]): Facts {
392	  const commits = new Set(sessions.flatMap((s) => s.commits));
393	  const files = new Set(sessions.flatMap((s) => s.filesTouched));
394	  const calls = sessions.reduce((n, s) => n + s.entries.filter((e) => e.kind === 'tool_call').length, 0);
395	  const minutes = sessions.reduce((n, s) => n + (s.endedAt ? (Date.parse(s.endedAt) - Date.parse(s.startedAt)) / 60000 : 0), 0);
396	  return {
397	    'sessions.count': sessions.length,
398	    'commits.count': commits.size,
399	    'files.count': files.size,
400	    'turns.total': sessions.reduce((n, s) => n + s.turnCount, 0),
401	    'tools.calls': calls,
402	    'tokens.output': sessions.reduce((n, s) => n + s.tokens.output, 0),
403	    'duration.minutes': Math.round(minutes),
404	  };
405	}
