import type { Entry, EntryKind, Session } from '@dailies/core';

export type PartialEntry = {
  kind: EntryKind;
  text?: string;
  ts?: string | null;
  toolName?: string;
  toolUseId?: string;
  command?: string;
  filePath?: string;
  isError?: boolean;
};

export function session(entries: PartialEntry[], opts: { id?: string } = {}): Session {
  const id = opts.id ?? 's1';
  const fullEntries: Entry[] = entries.map((e, index) => ({
    id: `${id}:${index}`,
    sessionId: id,
    index,
    ts: e.ts ?? null,
    kind: e.kind,
    text: e.text ?? '',
    toolName: e.toolName,
    toolUseId: e.toolUseId,
    command: e.command,
    filePath: e.filePath,
    isError: e.isError,
  }));
  return {
    id,
    checkpointIds: ['cp1'],
    agent: 'claude-code',
    model: 'claude-sonnet-4.6',
    branch: 'main',
    startedAt: '2026-10-10T07:00:00Z',
    endedAt: '2026-10-10T07:30:00Z',
    turnCount: fullEntries.length,
    tokens: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
    commits: [],
    filesTouched: [],
    entries: fullEntries,
  };
}

import { describe, expect, it } from 'vitest';
import { classifyCommand } from '../src/index';

describe('classifyCommand', () => {
  it('classifies commands', () => {
    expect(classifyCommand('cd app && pnpm test -- --run')).toBe('test');
    expect(classifyCommand('npx tsc --noEmit')).toBe('typecheck');
    expect(classifyCommand('git status')).toBe('other');
  });

  it('classifies lint and build commands', () => {
    expect(classifyCommand('pnpm run lint')).toBe('lint');
    expect(classifyCommand('next build')).toBe('build');
    expect(classifyCommand('make')).toBe('build');
  });

  it('treats "make test" as test, not build', () => {
    expect(classifyCommand('make test')).toBe('test');
  });

  it('prefers test over build when a command chain has both', () => {
    expect(classifyCommand('next build && pnpm test')).toBe('test');
  });
});

import { describe, expect, it } from 'vitest';
import { parseOutcome } from '../src/index';

describe('parseOutcome', () => {
  it('parses outcomes and strips colour codes', () => {
    expect(parseOutcome('test', '\u001b[31m Tests  2 failed\u001b[0m | 14 passed', false)).toBe('fail');
    expect(parseOutcome('test', ' Test Files  3 passed (3)\n Tests  14 passed (14)', false)).toBe('pass');
    expect(parseOutcome('test', 'ok  \tgithub.com/x/y\t0.21s', false)).toBe('pass');
    expect(parseOutcome('test', 'some unrelated text', false)).toBe('unknown');
    expect(parseOutcome('typecheck', 'src/a.ts(3,1): error TS2322: nope', false)).toBe('fail');
  });

  it('treats isError as fail regardless of the output text', () => {
    expect(parseOutcome('test', '14 passed', true)).toBe('fail');
  });

  it('does not treat a zero count as a failure marker', () => {
    expect(parseOutcome('test', '0 failed, 14 passed', false)).toBe('pass');
  });

  it('recognises typecheck pass and fail markers', () => {
    expect(parseOutcome('typecheck', 'Found 0 errors', false)).toBe('pass');
    expect(parseOutcome('typecheck', '', false)).toBe('pass');
    expect(parseOutcome('typecheck', 'Found 3 errors', false)).toBe('fail');
  });

  it('recognises build and lint pass/fail/unknown markers', () => {
    expect(parseOutcome('build', 'compiled successfully', false)).toBe('pass');
    expect(parseOutcome('build', '3 errors', false)).toBe('fail');
    expect(parseOutcome('lint', 'something unexpected', false)).toBe('unknown');
    expect(parseOutcome('lint', '0 problems', false)).toBe('pass');
  });
});

import { describe, expect, it } from 'vitest';
import { normalize, quoteMatches } from '../src/index';

describe('normalize', () => {
  it('collapses whitespace and strips markdown emphasis marks', () => {
    expect(normalize('  **bold**  _em_ `code`  spread   out ')).toBe('bold em code spread out');
  });
});

describe('quoteMatches', () => {
  it('matches a quote that differs by whitespace and Markdown marks, rejects a missing quote', () => {
    expect(quoteMatches('All tests pass now', 'Done. **All tests\n pass** now.')).toBe(true);
    expect(quoteMatches('All tests pass', 'I did not run the tests.')).toBe(false);
  });
});

import { describe, expect, it } from 'vitest';
import { lintStyle } from '../src/index';

describe('lintStyle', () => {
  it('accepts a clean short line', () => {
    expect(lintStyle('The fix closed the null check gap.')).toEqual([]);
  });

  it('flags more than one sentence', () => {
    expect(lintStyle('Tests passed. Build succeeded.').length).toBeGreaterThan(0);
  });

  it('flags more than 26 words', () => {
    const text = `${Array.from({ length: 27 }, () => 'word').join(' ')}.`;
    expect(lintStyle(text).length).toBeGreaterThan(0);
  });

  it('flags an em dash and an exclamation mark', () => {
    expect(lintStyle('Great work, truly excellent!').length).toBeGreaterThan(0);
    expect(lintStyle('Great work — a clean fix').length).toBeGreaterThan(0);
  });

  it('flags a spelled-out number from one to twenty', () => {
    expect(lintStyle('It took seven attempts to fix.').length).toBeGreaterThan(0);
  });

  it('flags a banned phrase', () => {
    expect(lintStyle('This is a seamless, robust solution.').length).toBeGreaterThan(0);
  });
});

