import { describe, expect, it } from 'vitest';
import { checkLine } from '../src/index';
import { session } from './helpers';
import type { DiffIndex, Facts, Line } from '@dailies/core';

const sess = session([{ kind: 'assistant', text: 'Touched 3 files in this change.' }]);
const facts: Facts = { 'files.count': 3 };
const diffs: DiffIndex = { 'abc123:src/retry.ts': '+function retry() {\n+  return true;\n+}' };

describe('checkLine', () => {
  it('accepts a clean line with grounded evidence', () => {
    const line: Line = {
      id: 'l1',
      text: 'The change touched 3 files.',
      evidence: [{ type: 'stat', key: 'files.count' }],
    };
    expect(checkLine(line, { sessions: [sess], facts, diffs })).toEqual({ ok: true, reasons: [] });
  });

  it('rejects an unknown entry ref', () => {
    const line: Line = {
      id: 'l2',
      text: 'The agent said so.',
      evidence: [{ type: 'entry', entryId: 'missing:0', quote: 'x' }],
    };
    const result = checkLine(line, { sessions: [sess], facts, diffs });
    expect(result.ok).toBe(false);
    expect(result.reasons.some((r) => r.includes('missing:0'))).toBe(true);
  });

  it('rejects a number not backed by any referenced evidence', () => {
    const line: Line = {
      id: 'l3',
      text: 'The change touched 5 files.',
      evidence: [{ type: 'stat', key: 'files.count' }],
    };
    const result = checkLine(line, { sessions: [sess], facts, diffs });
    expect(result.ok).toBe(false);
    expect(result.reasons.some((r) => r.includes('5'))).toBe(true);
  });

  it('rejects a banned phrase even when the evidence is otherwise clean', () => {
    const line: Line = {
      id: 'l4',
      text: 'This is a robust fix.',
      evidence: [{ type: 'stat', key: 'files.count' }],
    };
    const result = checkLine(line, { sessions: [sess], facts, diffs });
    expect(result.ok).toBe(false);
  });

  it('rejects an entry ref whose quote is not in the entry', () => {
    const line: Line = {
      id: 'l5',
      text: 'Something happened.',
      evidence: [{ type: 'entry', entryId: sess.entries[0]!.id, quote: 'nonexistent phrase' }],
    };
    expect(checkLine(line, { sessions: [sess], facts, diffs }).ok).toBe(false);
  });

  it('rejects a diff ref missing from the diff index', () => {
    const line: Line = {
      id: 'l6',
      text: 'Patched the retry loop.',
      evidence: [{ type: 'diff', sha: 'zzz', path: 'src/x.ts', quote: 'retry' }],
    };
    expect(checkLine(line, { sessions: [sess], facts, diffs }).ok).toBe(false);
  });

  it('skips the style lint when skipStyle is set', () => {
    const line: Line = {
      id: 'l7',
      text: 'This is a robust fix.',
      evidence: [{ type: 'stat', key: 'files.count' }],
    };
    expect(checkLine(line, { sessions: [sess], facts, diffs }, { skipStyle: true }).ok).toBe(true);
  });
});

export type CommandClass = 'test' | 'build' | 'typecheck' | 'lint' | 'other';

const PM = '(?:npm|pnpm|yarn|bun)';

const TEST_PATTERNS = [
  /\bvitest\b/,
  /\bjest\b/,
  /\bpytest\b/,
  /\bmocha\b/,
  /\bplaywright\s+test\b/,
  /\bgo\s+test\b/,
  /\bcargo\s+test\b/,
  /\bdotnet\s+test\b/,
  /\brspec\b/,
  /\bphpunit\b/,
  /\bpython\s+-m\s+unittest\b/,
  new RegExp(`\\b${PM}\\s+(?:run\\s+)?test\\b`),
  /\bmake\s+test\b/,
];

const TYPECHECK_PATTERNS = [/\btsc\b/, /\bmypy\b/, /\bpyright\b/];

const LINT_PATTERNS = [
  /\beslint\b/,
  /\bbiome\b/,
  /\bruff\b/,
  /\bflake8\b/,
  new RegExp(`\\b${PM}\\s+(?:run\\s+)?lint\\b`),
];

const BUILD_PATTERNS = [
  new RegExp(`\\b${PM}\\s+(?:run\\s+)?build\\b`),
  /\bnext\s+build\b/,
  /\bvite\s+build\b/,
  /\bcargo\s+build\b/,
  /\bgo\s+build\b/,
  /\bmake\b/,
];

const ORDER: [CommandClass, RegExp[]][] = [
  ['test', TEST_PATTERNS],
  ['typecheck', TYPECHECK_PATTERNS],
  ['lint', LINT_PATTERNS],
  ['build', BUILD_PATTERNS],
];

function classifyPart(part: string): CommandClass {
  for (const [cls, patterns] of ORDER) {
    if (patterns.some((re) => re.test(part))) return cls;
  }
  return 'other';
}

export function classifyCommand(command: string): CommandClass {
  const parts = command.split(/&&|\|\||[;|]/).map((p) => p.trim());
  const classes = new Set(parts.map(classifyPart));
  for (const [cls] of ORDER) {
    if (classes.has(cls)) return cls;
  }
  return 'other';
}

import type { Session } from '@dailies/core';
import { classifyCommand, type CommandClass } from './commands';

export type RunOutcome = 'pass' | 'fail' | 'unknown';

export interface ToolRun {
  callEntryId: string;
  resultEntryId: string | null;
  index: number;
  command: string;
  cls: CommandClass;
  outcome: RunOutcome;
}

const ANSI = /\x1b\[[0-9;]*[a-zA-Z]/g;

function stripAnsi(text: string): string {
  return text.replace(ANSI, '');
}

function parseTestOutcome(text: string): RunOutcome {
  const failCount = /(\d+)\s+(?:failed|failing)/.exec(text);
  if (failCount && Number(failCount[1]) > 0) return 'fail';
  if (/Tests?:\s+\d+\s+failed/.test(text)) return 'fail';
  if (/^FAIL\b/m.test(text)) return 'fail';
  if (/AssertionError/.test(text)) return 'fail';

  if (/\d+\s+passed/.test(text)) return 'pass';
  if (/^PASS\b/m.test(text)) return 'pass';
  if (/^ok\s+\S/m.test(text)) return 'pass';
  if (/test result: ok/.test(text)) return 'pass';

  return 'unknown';
}

function parseTypecheckOutcome(text: string): RunOutcome {
  if (/error TS\d+/.test(text)) return 'fail';
  if (/Found [1-9]\d*\s+errors?/.test(text)) return 'fail';
  if (/Found 0 errors/.test(text)) return 'pass';
  if (text.trim() === '') return 'pass';
  return 'unknown';
}

function parseLintOrBuildOutcome(text: string): RunOutcome {
  if (/[1-9]\d*\s+errors?/.test(text)) return 'fail';
  if (/[1-9]\d*\s+problems?/.test(text)) return 'fail';
  if (text.trim() === '') return 'pass';
  if (/compiled successfully/.test(text)) return 'pass';
  if (/built in/.test(text)) return 'pass';
  if (/Done in/.test(text)) return 'pass';
  if (/0 errors/.test(text)) return 'pass';
  if (/0 problems/.test(text)) return 'pass';
  return 'unknown';
}

export function parseOutcome(cls: CommandClass, output: string, isError: boolean): RunOutcome {
  if (isError) return 'fail';
  const text = stripAnsi(output);
  if (cls === 'test') return parseTestOutcome(text);
  if (cls === 'typecheck') return parseTypecheckOutcome(text);
  return parseLintOrBuildOutcome(text);
}

export function collectRuns(session: Session): ToolRun[] {
  const runs: ToolRun[] = [];
  for (const call of session.entries) {
    if (call.kind !== 'tool_call' || !call.command || call.toolUseId === undefined) continue;
    const cls = classifyCommand(call.command);
    if (cls === 'other') continue;
    const result = session.entries.find((e) => e.kind === 'tool_result' && e.toolUseId === call.toolUseId);
    const outcome: RunOutcome = result ? parseOutcome(cls, result.text, result.isError ?? false) : 'unknown';
    runs.push({
      callEntryId: call.id,
      resultEntryId: result?.id ?? null,
      index: call.index,
      command: call.command,
      cls,
      outcome,
    });
  }
  return runs;
}

export function normalize(text: string): string {
  return text.replace(/[*_`]/g, '').replace(/\s+/g, ' ').trim();
}

export function quoteMatches(quote: string, text: string): boolean {
  return normalize(text).includes(normalize(quote));
}

const BANNED_PHRASES = [
  'delve',
  'seamless',
  'robust',
  'leverage',
  'cutting-edge',
  'game-changer',
  'dive into',
  'unleash',
  'supercharge',
  'effortless',
  'revolutioniz',
  "it's worth noting",
  'not just',
];

const NUMBER_WORDS = [
  'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten',
  'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen',
  'eighteen', 'nineteen', 'twenty',
];

const NUMBER_WORD_RE = new RegExp(`\\b(?:${NUMBER_WORDS.join('|')})\\b`, 'i');

export function lintStyle(text: string): string[] {
  const reasons: string[] = [];

  const sentences = text
    .split(/[.!?]+/)
    .map((s) => s.trim())
    .filter(Boolean);
  if (sentences.length > 1) reasons.push('more than one sentence');

  const words = text.trim().split(/\s+/).filter(Boolean);
  if (words.length > 26) reasons.push('more than 26 words');

  if (/[—!]/.test(text)) reasons.push('contains an em dash or an exclamation mark');

  if (NUMBER_WORD_RE.test(text)) reasons.push('spells out a number instead of using a digit');

  for (const phrase of BANNED_PHRASES) {
    if (text.toLowerCase().includes(phrase.toLowerCase())) reasons.push(`banned phrase: ${phrase}`);
  }

  return reasons;
}

import type { DiffIndex, Facts, Line, Session } from '@dailies/core';
import { quoteMatches } from './quote';
import { lintStyle } from './style';

const NUMBER_RE = /\d+(?:\.\d+)?/g;

export function checkLine(
  line: Line,
  ctx: { sessions: Session[]; facts: Facts; diffs: DiffIndex },
  o: { skipStyle?: boolean } = {}
): { ok: boolean; reasons: string[] } {
  const reasons: string[] = [];
  const entryById = new Map<string, { text: string }>();
  for (const s of ctx.sessions) for (const e of s.entries) entryById.set(e.id, e);

  const numbersInText = line.text.match(NUMBER_RE) ?? [];
  const groundedNumbers = new Set<string>();

  for (const ref of line.evidence) {
    if (ref.type === 'entry') {
      const entry = entryById.get(ref.entryId);
      if (!entry) {
        reasons.push(`unknown entry: ${ref.entryId}`);
        continue;
      }
      if (ref.quote && !quoteMatches(ref.quote, entry.text)) {
        reasons.push(`quote not found in entry ${ref.entryId}`);
      }
      for (const n of numbersInText) if (entry.text.includes(n)) groundedNumbers.add(n);
    } else if (ref.type === 'diff') {
      const key = `${ref.sha}:${ref.path}`;
      const patch = ctx.diffs[key];
      if (patch === undefined) {
        reasons.push(`unknown diff: ${key}`);
        continue;
      }
      if (ref.quote && !quoteMatches(ref.quote, patch)) {
        reasons.push(`quote not found in diff ${key}`);
      }
      for (const n of numbersInText) if (patch.includes(n)) groundedNumbers.add(n);
    } else {
      if (!(ref.key in ctx.facts)) {
        reasons.push(`unknown stat: ${ref.key}`);
        continue;
      }
      const value = String(ctx.facts[ref.key]);
      for (const n of numbersInText) if (n === value) groundedNumbers.add(n);
    }
  }

  for (const n of numbersInText) {
    if (!groundedNumbers.has(n)) reasons.push(`number not grounded in evidence: ${n}`);
  }

  if (!o.skipStyle) reasons.push(...lintStyle(line.text));

  return { ok: reasons.length === 0, reasons };
}

import type { Claim, Entry, EvidenceRef, Session } from '@dailies/core';
import type { CommandClass } from './commands';
import { classifyCommand } from './commands';
import { collectRuns, parseOutcome, type ToolRun } from './results';
import { normalize, quoteMatches } from './quote';

type Verdicted = Pick<Claim, 'verdict' | 'reason' | 'evidence'>;

const EDIT_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit']);

function findEntry(session: Session, entryId: string): Entry | undefined {
  return session.entries.find((e) => e.id === entryId);
}

function entryRef(entryId: string): EvidenceRef {
  return { type: 'entry', entryId };
}

function runEvidence(run: ToolRun): EvidenceRef[] {
  const refs: EvidenceRef[] = [entryRef(run.callEntryId)];
  if (run.resultEntryId) refs.push(entryRef(run.resultEntryId));
  return refs;
}

function unverifiable(reason: string): Verdicted {
  return { verdict: 'unverifiable', reason, evidence: [] };
}

// Shared by tests_pass (class ['test']) and build_passes (classes ['build', 'typecheck', 'lint']):
// consider the last matching run before the claim's entry, then check for an edit since.
function lastRunVerdict(claim: Claim, session: Session, classes: CommandClass[], noRunReason: string): Verdicted {
  const claimEntry = findEntry(session, claim.entryId);
  if (!claimEntry) return unverifiable('claim entry not found in session');

  const runs = collectRuns(session).filter((r) => classes.includes(r.cls) && r.index < claimEntry.index);
  if (runs.length === 0) return unverifiable(noRunReason);

  const last = runs[runs.length - 1]!;
  if (last.outcome === 'fail') return { verdict: 'contradicted', reason: 'the last recorded run failed', evidence: runEvidence(last) };
  if (last.outcome === 'unknown') return unverifiable('the last recorded run output was not recognised');

  const edit = session.entries.find(
    (e) =>
      e.kind === 'tool_call' &&
      e.index > last.index &&
      e.index < claimEntry.index &&
      e.toolName !== undefined &&
      EDIT_TOOLS.has(e.toolName) &&
      e.filePath !== undefined &&
      !e.filePath.endsWith('.md')
  );
  if (edit) {
    return {
      verdict: 'stale',
      reason: 'a source file was edited after the last passing run',
      evidence: [entryRef(edit.id), ...runEvidence(last)],
    };
  }
  return { verdict: 'verified', reason: 'the last recorded run passed with no edits after', evidence: runEvidence(last) };
}

function ranCommand(claim: Claim, session: Session): Verdicted {
  const claimEntry = findEntry(session, claim.entryId);
  if (!claimEntry || !claim.subject) return unverifiable('no matching command is recorded before this message');

  const subject = normalize(claim.subject);
  const calls = session.entries.filter(
    (e) => e.kind === 'tool_call' && e.index < claimEntry.index && e.command && normalize(e.command).includes(subject)
  );
  if (calls.length === 0) return unverifiable('no matching command is recorded before this message');

  const call = calls[calls.length - 1]!;
  const result = session.entries.find((e) => e.kind === 'tool_result' && e.toolUseId === call.toolUseId);
  if (!result) return unverifiable('the matching command has no recorded result');

  const evidence = [entryRef(call.id), entryRef(result.id)];
  if (result.isError) return { verdict: 'contradicted', reason: 'the matching command errored', evidence };
  return { verdict: 'verified', reason: 'the matching command succeeded', evidence };
}

function fixedError(claim: Claim, session: Session): Verdicted {
  const claimEntry = findEntry(session, claim.entryId);
  if (!claimEntry || !claim.subject) return unverifiable('no error text is recorded for this claim');

  const subject = normalize(claim.subject);
  const errorResult = session.entries.find(
    (e) => e.kind === 'tool_result' && e.index < claimEntry.index && normalize(e.text).includes(subject)
  );
  if (!errorResult) return unverifiable('the error text is not recorded in any tool result');

  const errorCall = session.entries.find((e) => e.kind === 'tool_call' && e.toolUseId === errorResult.toolUseId);
  if (!errorCall || !errorCall.command) return unverifiable('the failing command is not recorded');
  const cls = classifyCommand(errorCall.command);

  const laterCalls = session.entries.filter(
    (e) =>
      e.kind === 'tool_call' &&
      e.index > errorResult.index &&
      e.index < claimEntry.index &&
      e.command &&
      classifyCommand(e.command) === cls
  );
  if (laterCalls.length === 0) return unverifiable('no later run of the same kind is recorded before this message');

  const lastCall = laterCalls[laterCalls.length - 1]!;
  const lastResult = session.entries.find((e) => e.kind === 'tool_result' && e.toolUseId === lastCall.toolUseId);
  const outcome = lastResult ? parseOutcome(cls, lastResult.text, lastResult.isError ?? false) : 'unknown';
  const stillPresent = lastResult ? normalize(lastResult.text).includes(subject) : false;

  const evidence: EvidenceRef[] = [entryRef(errorResult.id), entryRef(lastCall.id)];
  if (lastResult) evidence.push(entryRef(lastResult.id));

  if (stillPresent || outcome === 'fail') {
    return { verdict: 'contradicted', reason: 'the error is still present in a later run', evidence };
  }
  return { verdict: 'verified', reason: 'a later run no longer shows the error', evidence };
}

export function verifyClaim(claim: Claim, session: Session): Claim {
  if (claim.kind === 'implemented') return claim;

  const entry = findEntry(session, claim.entryId);
  if (!entry || !quoteMatches(claim.quote, entry.text)) {
    return { ...claim, verdict: 'unverifiable', reason: 'quote not found in transcript', evidence: [] };
  }

  let result: Verdicted;
  switch (claim.kind) {
    case 'tests_pass':
      result = lastRunVerdict(claim, session, ['test'], 'no test run is recorded before this message');
      break;
    case 'build_passes':
      result = lastRunVerdict(claim, session, ['build', 'typecheck', 'lint'], 'no build, typecheck or lint run is recorded before this message');
      break;
    case 'ran_command':
      result = ranCommand(claim, session);
      break;
    case 'fixed_error':
      result = fixedError(claim, session);
      break;
    default:
      result = unverifiable('unknown claim kind');
  }
  return { ...claim, ...result };
}

export function verifyClaims(claims: Claim[], sessions: Session[]): Claim[] {
  const byId = new Map(sessions.map((s) => [s.id, s]));
  return claims.map((c) => {
    const session = byId.get(c.sessionId);
    if (!session) return { ...c, verdict: 'unverifiable', reason: 'session not found', evidence: [] };
    return verifyClaim(c, session);
  });
}

